    gsl.gsl_diff_backward.argtypes = [
        ctypes.c_void_p,
        ctypes.c_double,
        ctypes.POINTER(ctypes.c_double),
        ctypes.POINTER(ctypes.c_double)
    ]
    gsl.gsl_diff_backward.restype = ctypes.c_int

    # Create a GSL function wrapper
    class GSLFunctionWrapper(ctypes.Structure):
        _fields_ = [("f", ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double))]

    # Convert Python function to C function pointer
    def py_func(x):
        return float(func(x))

    c_func = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(py_func)
    gsl_func = GSLFunctionWrapper(f=c_func)

    # Prepare output variables
