    abserr = ctypes.c_double()

    # Call the GSL function
    status = gsl.gsl_diff_backward(
        ctypes.byref(gsl_func),
        x,
        ctypes.byref(result),
        ctypes.byref(abserr)
    )

    if status != 0:
        raise RuntimeError("GSL error in derivative computation")

    return (result.value, abserr.value)

