class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = matrix
        self.n = len(matrix)
        self.data = (ctypes.c_double * (self.n * self.n))()
        for i in range(self.n):
            for j in range(self.n):
                self.data[i * self.n + j] = matrix[i][j]
        self.array = ctypes.pointer(self.data)

    def get_data_pointer(self):
        return self.array

    def to_list(self):
        result = [[0.0 for _ in range(self.n)] for _ in range(self.n)]
        for i in range(self.n):
            for j in range(self.n):
                result[i][j] = self.data[i * self.n + j]
        return result

def is_positive_definite(matrix):
    try:
        # Check if the matrix is symmetric
        n = len(matrix)
        for i in range(n):
            for j in range(n):
                if abs(matrix[i][j] - matrix[j][i]) > 1e-10:
                    return False
        # Check if all eigenvalues are positive
        import numpy as np
        mat = np.array(matrix, dtype=np.float64)
        eigenvalues = np.linalg.eigvalsh(mat)
        return np.all(eigenvalues > 1e-10)
    except Exception as e:
        print(f"Error checking positive definiteness: {e}")
        return False

def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite.")

    # Load the required dynamic libraries
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
