    gsl.gsl_linalg_cholesky_decomp.argtypes = [
        ctypes.POINTER(ctypes.POINTER(ctypes.c_double)),
        ctypes.POINTER(ctypes.POINTER(ctypes.c_double)),
        ctypes.POINTER(ctypes.c_int)
    ]
    gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

    # Create GSLMatrix instance
    gsl_matrix = GSLMatrix(matrix)
    L = GSLMatrix([[0.0 for _ in range(gsl_matrix.n)] for _ in range(gsl_matrix.n)])

    # Perform Cholesky decomposition
    status = gsl.gsl_linalg_cholesky_decomp(
        gsl_matrix.get_data_pointer(),
        L.get_data_pointer(),
        ctypes.pointer(ctypes.c_int(gsl_matrix.n))
    )

    if status != 0:
        raise RuntimeError("Cholesky decomposition failed.")

    return L.to_list()

