        self.workspace = gsl.gsl_rstat_quantile_alloc()
        if not self.workspace:
            raise RuntimeError("Failed to allocate quantile workspace.")

    def reset(self):
        gsl.gsl_rstat_quantile_reset(self.workspace)

    def add(self, value):
        gsl.gsl_rstat_quantile_add(self.workspace, ctypes.c_double(value))

    def get_quantile(self, p):
        if not (0.0 <= p <= 1.0):
            raise ValueError("p must be between 0.0 and 1.0.")
        result = ctypes.c_double()
        gsl.gsl_rstat_quantile_get(self.workspace, ctypes.c_double(p), ctypes.byref(result))
        return result.value

    def free(self):
        gsl.gsl_rstat_quantile_free(self.workspace)

    def compute_quantile(self, p, values):
        if not (0.0 <= p <= 1.0):
            raise ValueError("p must be between 0.0 and 1.0.")
        if not isinstance(values, list):
            raise TypeError("values must be a list of numerical values.")
        self.reset()
        for val in values:
            self.add(val)
        return self.get_quantile(p)

    def __del__(self):
        self.free()

